    headers: { 'Content-Type': 'application/json', 'x-cron-secret': env('CRON_SECRET'), apikey: env('SUPABASE_ANON_KEY'), Authorization: `Bearer ${env('SUPABASE_ANON_KEY')}` },
    body: JSON.stringify(body),
