cat > "$D/cal-webhook/index.ts" <<'EOF_32_CALWEBHOOK'
// Cal.com booking webhook -> Evo CRM.
//
//   POST from Cal.com, header x-cal-signature-256 = hex HMAC-SHA256 of the raw body
//
// A booked, rescheduled or cancelled Discovery Call updates the contact in the CRM and keeps one Sales card for them:
//   booked / rescheduled -> contact labelled "call-booked", card in Sales > Qualification (moved forward only)
//   cancelled            -> label swapped to "call-cancelled", the card stays where it is
// Anything else Cal.com sends is acknowledged and ignored.
//
// The webhook secret is derived, not stored: sha256("cal-webhook:" + AGENT_TOOLS_SECRET), so a leak from Cal.com
// does not expose the agent tools secret. Paste that value into the Cal.com webhook's "Secret" box.
//
// Env: AGENT_TOOLS_SECRET, CRM_API_URL, CRM_SERVICE_TOKEN.
import { serve } from 'https://deno.land/std@0.177.1/http/server.ts';
import { env, json } from '../_shared/flutterwave.ts';
import { ensureItem, upsertContact } from '../_shared/crm.ts';

const hex = (buffer: ArrayBuffer) => [...new Uint8Array(buffer)].map((b) => b.toString(16).padStart(2, '0')).join('');

async function webhookSecret() {
  const base = env('AGENT_TOOLS_SECRET');
  if (!base) return '';
  return hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`cal-webhook:${base}`)));
}

async function sign(secret: string, body: string) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(body)));
}

function same(a: string, b: string) {
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const text = (v: unknown, max: number) => {
  const s = typeof v === 'string' ? v.trim() : '';
  return s ? s.slice(0, max) : undefined;
};

serve(async (req) => {
  if (req.method !== 'POST') return json({ error: 'Use POST.' }, 405);
  const raw = await req.text();
  const secret = await webhookSecret();
  const given = (req.headers.get('x-cal-signature-256') ?? '').toLowerCase();
  if (!secret || !same(given, await sign(secret, raw))) return json({ error: 'Not authorised.' }, 401);

  let body: any;
  try {
    body = JSON.parse(raw);
  } catch {
    return json({ error: 'Bad JSON.' }, 400);
  }
  const event = String(body?.triggerEvent ?? '');
  if (!['BOOKING_CREATED', 'BOOKING_RESCHEDULED', 'BOOKING_CANCELLED'].includes(event)) return json({ ok: true, ignored: event });

  try {
    const p = body.payload ?? {};
    const answers = p.responses ?? {};
    const answer = (key: string) => {
      const v = answers[key];
      return text(v && typeof v === 'object' && 'value' in v ? v.value : v, 600);
    };
    const attendee = (p.attendees ?? [])[0] ?? {};
    const email = String(answer('email') ?? attendee.email ?? '').toLowerCase();
    if (!email) return json({ ok: true, ignored: 'no attendee email' });
    const name = answer('name') ?? text(attendee.name, 120) ?? email.split('@')[0];
    const phone = answer('attendeePhoneNumber') ?? text(attendee.phoneNumber, 40);
    const cancelled = event === 'BOOKING_CANCELLED';

    const saved = await upsertContact({
      email,
      name,
      phone,
      firstTouch: { lead_channel: 'call_booking', lead_source: 'cal-discovery-call' },
      attrs: cancelled
        ? {}
        : {
            lifecycle_stage: 'lead',
            business_industry: answer('Practice'),
            business_age: answer('Durationinpractice'),
            main_goal: text(answer('Challenges'), 300),
            whatsapp: phone,
          },
      labels: [cancelled ? 'call-cancelled' : 'call-booked'],
      removeLabels: [cancelled ? 'call-booked' : 'call-cancelled'],
    });

    await ensureItem(saved.id, {
      pipeline: 'sales',
      stage: 'Qualification',
      advance: !cancelled,
      create: !cancelled,
      fields: {
        entry_point: 'discovery_call',
        call_status: cancelled ? 'cancelled' : event === 'BOOKING_RESCHEDULED' ? 'rescheduled' : 'booked',
        call_at: text(p.startTime, 40),
        // Only a real link: Cal.com sometimes sends just the location type ("integrations:google:meet").
        call_link: [p.metadata?.videoCallUrl, p.videoCallData?.url, p.location].map((v) => text(v, 300)).find((v) => v?.startsWith('http')),
        follow_up_process: answer('Process'),
        source_record_id: text(p.uid, 80),
      },
    });
    return json({ ok: true, event, contact: saved.id });
  } catch (error) {
    console.error('cal-webhook failed', error);
    // 500 makes Cal.com retry the delivery.
    return json({ error: (error as Error).message ?? 'The update failed.' }, 500);
  }
});
EOF_32_CALWEBHOOK
echo "wrote cal-webhook/index.ts"

cat > "$D/crm-cleanup/index.ts" <<'EOF_33_CRMCLEANUP'
// Daily sweep: deletes the empty contacts the CRM chat widget creates for visitors who never chatted.
//
//   POST (header x-cron-secret: <CRON_SECRET>)           -> deletes, returns { checked, deleted, kept }
//   POST ?dry=1                                          -> only reports what it would delete
//
// A contact is removed only when ALL of these hold:
//   - no email, no phone number and no identifier
//   - a name in the widget's random style (word-word-123)
//   - created more than 24 hours ago
//   - no conversation at all (if that cannot be read, it is kept)
// At most MAX_DELETES per run. Everything else, including people who started a chat, is left alone.
//
// Env: CRON_SECRET, CRM_API_URL, CRM_SERVICE_TOKEN.
import { serve } from 'https://deno.land/std@0.177.1/http/server.ts';
import { env, json } from '../_shared/flutterwave.ts';

const MAX_DELETES = 300;
const MAX_PAGES = 30;
const MIN_AGE_SECONDS = 24 * 3600;
const ANON_NAME = /^[a-z]+-[a-z]+-\d+$/;

async function crm(method: string, path: string) {
  const base = env('CRM_API_URL').replace(/\/$/, '');
  const response = await fetch(`${base}/api/v1${path}`, {
    method,
    headers: { 'X-Service-Token': env('CRM_SERVICE_TOKEN') },
    signal: AbortSignal.timeout(20000),
  });
  const text = await response.text();
  let body: any = {};
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    body = {};
  }
  return { ok: response.ok, body };
}

serve(async (req) => {
  if (req.method !== 'POST') return json({ error: 'Use POST.' }, 405);
  const secret = env('CRON_SECRET');
  if (!secret || req.headers.get('x-cron-secret') !== secret) return json({ error: 'Not authorised.' }, 401);
  if (!env('CRM_API_URL') || !env('CRM_SERVICE_TOKEN')) return json({ error: 'CRM_API_URL and CRM_SERVICE_TOKEN are not set.' }, 503);
  const dry = new URL(req.url).searchParams.get('dry') === '1';

  const cutoff = Date.now() / 1000 - MIN_AGE_SECONDS;
  const candidates: { id: string; name: string }[] = [];
  let checked = 0;
  for (let page = 1; page <= MAX_PAGES; page += 1) {
    const { ok, body } = await crm('GET', `/contacts?per_page=100&page=${page}`);
    if (!ok) return json({ error: 'Could not read the CRM contacts.', checked, deleted: 0 }, 502);
    const rows: any[] = body?.data?.contacts ?? body?.data ?? [];
    checked += rows.length;
    for (const c of rows) {
      if (c.email || c.phone_number || c.identifier) continue;
      if (!ANON_NAME.test(String(c.name ?? ''))) continue;
      if (typeof c.created_at === 'number' && c.created_at > cutoff) continue;
      candidates.push({ id: c.id, name: c.name });
    }
    if (rows.length < 100) break;
  }

  let deleted = 0;
  let kept = 0;
  const wouldDelete: string[] = [];
  for (const c of candidates) {
    if (deleted + wouldDelete.length >= MAX_DELETES) break;
    const { ok, body } = await crm('GET', `/contacts/${c.id}/conversations`);
    const list = body?.data?.payload ?? body?.data;
    // Unknown means keep: only a clearly empty list lets the contact go.
    if (!ok || !Array.isArray(list) || list.length > 0) {
      kept += 1;
      continue;
    }
    if (dry) {
      wouldDelete.push(c.name);
      continue;
    }
    const removed = await crm('DELETE', `/contacts/${c.id}`);
    if (removed.ok) deleted += 1;
    else kept += 1;
  }
  return json(dry ? { dry: true, checked, candidates: candidates.length, wouldDelete: wouldDelete.length, kept, sample: wouldDelete.slice(0, 5) } : { checked, candidates: candidates.length, deleted, kept });
});
EOF_33_CRMCLEANUP
echo "wrote crm-cleanup/index.ts"

cat > "$D/group-sync/index.ts" <<'EOF_34_GROUPSYNC'
// Adds paying members to the Breadmaker WhatsApp groups through Evolution API.
//
//   POST (header x-cron-secret: <CRON_SECRET>)  ->  { done, invited, failed, waiting }
//
// breadmaker.group_queue is filled by database triggers on payments and memberships. For each pending "add":
//   1. find the person's WhatsApp number (payment, then application),
//   2. add them to the group; if WhatsApp refuses (privacy settings) send them the invite link instead,
//   3. retry with a growing delay on errors (6 tries), keeping last_error on the row.
// Groups with no group_jid yet are skipped: their queued members wait. "remove" rows are never run here.
// The General group waits until the person's community add is done.
//
// Env: CRON_SECRET, EVOLUTION_API_URL, EVOLUTION_API_KEY, EVOLUTION_INSTANCE, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY.
import { serve } from 'https://deno.land/std@0.177.1/http/server.ts';
import { admin, env, json } from '../_shared/flutterwave.ts';
import { normalisePhone } from '../_shared/crm.ts';

const MAX_TRIES = 6;
const BATCH = 10;

async function evolution(method: string, path: string, body?: unknown) {
  const base = env('EVOLUTION_API_URL').replace(/\/$/, '');
  const response = await fetch(`${base}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json', apikey: env('EVOLUTION_API_KEY') },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: AbortSignal.timeout(25000),
  });
  const text = await response.text();
  let parsed: any = {};
  try {
    parsed = text ? JSON.parse(text) : {};
  } catch {
    parsed = { raw: text };
  }
  if (!response.ok) throw new Error(`Evolution ${method} ${path} -> ${response.status} ${text.slice(0, 200)}`);
  return parsed;
}

async function findPhone(db: ReturnType<typeof admin>, email: string): Promise<string | null> {
  const fromPayment = await db.from('payments').select('phone').ilike('email', email).not('phone', 'is', null).order('created_at', { ascending: false }).limit(5);
  for (const row of fromPayment.data ?? []) {
    const phone = normalisePhone(row.phone);
    if (phone) return phone;
  }
  const fromApplication = await db.from('applications').select('phone').ilike('email', email).not('phone', 'is', null).order('created_at', { ascending: false }).limit(5);
  for (const row of fromApplication.data ?? []) {
    const phone = normalisePhone(row.phone);
    if (phone) return phone;
  }
  return null;
}

serve(async (req) => {
  if (req.method !== 'POST') return json({ error: 'Use POST.' }, 405);
  const secret = env('CRON_SECRET');
  if (!secret || req.headers.get('x-cron-secret') !== secret) return json({ error: 'Not authorised.' }, 401);
  if (!env('EVOLUTION_API_URL') || !env('EVOLUTION_API_KEY') || !env('EVOLUTION_INSTANCE')) {
    return json({ error: 'EVOLUTION_API_URL, EVOLUTION_API_KEY and EVOLUTION_INSTANCE are not set.' }, 503);
  }
  const instance = encodeURIComponent(env('EVOLUTION_INSTANCE'));

  // ?list=1 lists the groups this number is in, so their ids can be copied into whatsapp_groups.group_jid.
  if (new URL(req.url).searchParams.get('list') === '1') {
    const all = await evolution('GET', `/group/fetchAllGroups/${instance}?getParticipants=false`);
    return json((Array.isArray(all) ? all : []).map((g: any) => ({ id: g.id, name: g.subject, members: g.size })));
  }

  const db = admin();
  const { data: groups } = await db.from('whatsapp_groups').select('key, label, group_jid').eq('enabled', true).not('group_jid', 'is', null);
  const byKey = new Map((groups ?? []).map((g: any) => [g.key, g]));
  if (!byKey.size) return json({ done: 0, invited: 0, failed: 0, waiting: 0, note: 'No group ids set yet.' });

  const { data: rows, error } = await db
    .from('group_queue')
    .select('*')
    .eq('status', 'pending')
    .eq('action', 'add')
    .in('group_key', [...byKey.keys()])
    .lte('next_attempt_at', new Date().toISOString())
    .order('id')
    .limit(BATCH);
  if (error) return json({ error: error.message }, 500);

  // The General group needs the person to be in the community first: wait while their community add is still open.
  const generalEmails = (rows ?? []).filter((r: any) => r.group_key === 'community_general').map((r: any) => r.email);
  const { data: openCommunity } = generalEmails.length
    ? await db.from('group_queue').select('email').eq('group_key', 'community').eq('action', 'add').eq('status', 'pending').in('email', generalEmails)
    : { data: [] as { email: string }[] };
  const holdBack = new Set((openCommunity ?? []).map((r: any) => r.email));

  let done = 0;
  let invited = 0;
  let failed = 0;
  for (const row of rows ?? []) {
    if (row.group_key === 'community_general' && holdBack.has(row.email)) continue;
    const group = byKey.get(row.group_key) as { label: string; group_jid: string };
    const finish = (status: string, note = '', lastError = '') =>
      db.from('group_queue').update({ status, note, last_error: lastError, done_at: new Date().toISOString(), tries: row.tries + 1 }).eq('id', row.id);
    try {
      const phone = await findPhone(db, row.email);
      if (!phone) {
        await finish('failed', 'no phone number on file', 'no phone number on file');
        failed += 1;
        continue;
      }
      const number = phone.replace(/^\+/, '');
      let direct = false;
      try {
        const result = await evolution('POST', `/group/updateParticipant/${instance}?groupJid=${encodeURIComponent(group.group_jid)}`, {
          action: 'add',
          participants: [number],
        });
        const statuses = (Array.isArray(result?.updateParticipants) ? result.updateParticipants : Array.isArray(result) ? result : []).map((p: any) => String(p.status ?? ''));
        // 200 added, 409 already in the group.
        direct = statuses.length > 0 && statuses.every((s: string) => s === '200' || s === '409');
      } catch (error) {
        console.warn('group add refused, falling back to invite', (error as Error).message);
      }
      if (direct) {
        await finish('done', 'added');
        done += 1;
        continue;
      }
      // WhatsApp would not add them directly: send the invite link instead.
      const invite = await evolution('GET', `/group/inviteCode/${instance}?groupJid=${encodeURIComponent(group.group_jid)}`);
      const link = invite?.inviteUrl ?? (invite?.code ? `https://chat.whatsapp.com/${invite.code}` : null);
      if (!link) throw new Error('No invite link returned');
      await evolution('POST', `/message/sendText/${instance}`, {
        number,
        text: `Welcome to ${group.label}. Join on WhatsApp here: ${link}`,
      });
      await finish('invited', 'invite link sent');
      invited += 1;
    } catch (error) {
      const message = (error as Error).message.slice(0, 500);
      const tries = row.tries + 1;
      if (tries >= MAX_TRIES) {
        await db.from('group_queue').update({ status: 'failed', tries, last_error: message, done_at: new Date().toISOString() }).eq('id', row.id);
        failed += 1;
      } else {
        const delayMinutes = Math.min(120, 2 ** tries);
        await db.from('group_queue').update({ tries, last_error: message, next_attempt_at: new Date(Date.now() + delayMinutes * 60_000).toISOString() }).eq('id', row.id);
      }
    }
  }

  const { count } = await db.from('group_queue').select('id', { count: 'exact', head: true }).eq('status', 'pending').eq('action', 'add');
  return json({ done, invited, failed, waiting: count ?? 0 });
});
EOF_34_GROUPSYNC
echo "wrote group-sync/index.ts"

cat > "$D/_deploy/sync.sh" <<'EOF_35__DEPLOY'
#!/bin/bash
# Pulls this repo's edge functions into the edge-functions container from the functions-sync service, so a git push
# deploys them. Runs INSIDE the supabase edge-functions container (a Coolify scheduled task runs it every minute),
# and needs only bash, sha256sum and awk: the container has no curl, git or node.
#
#   bash sync.sh               pull whatever changed
#   DRY=1 bash sync.sh         say what would change, change nothing
#   FORCE=1 bash sync.sh       ignore a pause
#   touch $D/_deploy/pause     stop syncing (remove the file to resume), for a hotfix you are testing by hand
#
# How it stays safe:
#   - Only files listed in the repo's deploy-manifest.json are touched, and none is ever deleted.
#   - Every file is downloaded and checked against its SHA-256 before anything is replaced; if any download or check
#     fails, nothing is replaced and the next run tries again.
#   - Replaced files are copied to _deploy/backup/<old version>/ first (the last 5 versions are kept).
#   - Edge functions are read from disk on each request, so no restart is needed.
# Plain HTTP on the Docker network only: the service has no public address.
set -u

HOST="${SYNC_HOST:-functions-sync-breadmaker}"
PORT="${SYNC_PORT:-8080}"
D="${FUNCTIONS_DIR:-/home/deno/functions}"
STATE="$D/_deploy"
mkdir -p "$STATE/backup" "$STATE/stage"
LOG="$STATE/sync.log"

log() {
  echo "$(date -u +%FT%TZ) $*" | tee -a "$LOG"
  if [ "$(wc -l < "$LOG")" -gt 400 ]; then tail -n 200 "$LOG" > "$LOG.tmp" && mv "$LOG.tmp" "$LOG"; fi
}

# GET <path> from the service; the body goes to stdout. Fails (returns 1) on anything but a 200.
http_get() {
  local line status
  exec 3<>"/dev/tcp/$HOST/$PORT" || return 1
  printf 'GET %s HTTP/1.0\r\nHost: %s\r\nConnection: close\r\n\r\n' "$1" "$HOST" >&3
  IFS= read -r status <&3
  case "$status" in *" 200"*) ;; *) exec 3>&-; return 1 ;; esac
  while IFS= read -r line <&3; do [ "$line" = $'\r' ] && break; done
  cat <&3
  exec 3>&-
}

if [ -f "$STATE/pause" ] && [ -z "${FORCE:-}" ]; then
  echo "paused ($STATE/pause exists)"
  exit 0
fi

manifest="$(http_get /manifest.txt)" || { log "cannot reach the functions-sync service at $HOST:$PORT"; exit 2; }
version="$(echo "$manifest" | awk '$1=="version"{print $2}')"
commit="$(echo "$manifest" | awk '$1=="commit"{print $2}')"
[ -n "$version" ] || { log "the manifest has no version, ignoring it"; exit 2; }

# 1. work out what differs
changes=()
while read -r sha size file; do
  case "$sha" in version | commit | built) continue ;; esac
  [ -n "$file" ] || continue
  have="$(sha256sum "$D/$file" 2>/dev/null | cut -d' ' -f1)"
  [ "$have" = "$sha" ] || changes+=("$sha $file")
done <<< "$manifest"

if [ "${#changes[@]}" -eq 0 ]; then
  echo "up to date ($version)"
  printf 'version=%s\ncommit=%s\nchecked=%s\nstatus=up to date\n' "$version" "$commit" "$(date -u +%FT%TZ)" > "$STATE/state"
  exit 0
fi

if [ -n "${DRY:-}" ]; then
  echo "would update ${#changes[@]} file(s) to $version:"
  for entry in "${changes[@]}"; do echo "  ${entry#* }"; done
  exit 0
fi

# 2. download and verify everything before replacing anything
stage="$STATE/stage/$version"
rm -rf "$stage"
for entry in "${changes[@]}"; do
  sha="${entry%% *}"
  file="${entry#* }"
  mkdir -p "$stage/$(dirname "$file")"
  if ! http_get "/f/$file" > "$stage/$file"; then log "download failed: $file (nothing replaced)"; rm -rf "$stage"; exit 3; fi
  got="$(sha256sum "$stage/$file" | cut -d' ' -f1)"
  if [ "$got" != "$sha" ]; then log "checksum mismatch: $file (nothing replaced)"; rm -rf "$stage"; exit 3; fi
done

# 3. back up what is there, then replace
previous="$(awk -F= '$1=="version"{print $2}' "$STATE/state" 2>/dev/null)"
backup="$STATE/backup/${previous:-initial}-before-$version"
for entry in "${changes[@]}"; do
  file="${entry#* }"
  if [ -f "$D/$file" ]; then
    mkdir -p "$backup/$(dirname "$file")"
    cp "$D/$file" "$backup/$file"
  fi
  mkdir -p "$(dirname "$D/$file")"
  mv "$stage/$file" "$D/$file.sync.$$" && mv "$D/$file.sync.$$" "$D/$file"
done
rm -rf "$stage"
ls -1t "$STATE/backup" 2>/dev/null | tail -n +6 | while read -r old; do rm -rf "$STATE/backup/$old"; done

printf 'version=%s\ncommit=%s\nchecked=%s\nstatus=deployed %s file(s)\n' "$version" "$commit" "$(date -u +%FT%TZ)" "${#changes[@]}" > "$STATE/state"
log "deployed $version (commit ${commit:-unknown}): ${#changes[@]} file(s): $(for entry in "${changes[@]}"; do printf '%s ' "${entry#* }"; done)"
exit 0
EOF_35__DEPLOY
echo "wrote _deploy/sync.sh"

echo
echo "Done. $(ls "$D" | tr '
' ' ')"
echo "Now restart the supabase-edge-functions container so the changes load."
